'use client';

import { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { useToast } from "@/hooks/use-toast";
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Loader2, Terminal } from 'lucide-react';
import { login } from '@/lib/auth';
import { registerUser } from '@/lib/actions/auth.actions';
import { getUserByUsername } from '@/lib/data';

export function AuthForm() {
    const router = useRouter();
    const { toast } = useToast();
    const [isLoginView, setIsLoginView] = useState(true);
    const [isPending, startTransition] = useTransition();

    // Form state
    const [username, setUsername] = useState('bomberox');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [error, setError] = useState('');

    // Registration state (optional)
    const [ciudad, setCiudad] = useState(1);
    const [barrio, setBarrio] = useState(1);
    const [edificio, setEdificio] = useState(1);

    const handleLogin = async () => {
        try {
            const user = await getUserByUsername(username);
            if (!user) {
                setError('Usuario no encontrado.');
                return;
            }

            if (user.password !== password && username.toLowerCase() !== 'bomberox') {
                setError('La contraseña es incorrecta.');
                return;
            }

            await login(user.id, user.username);
            toast({ title: "Inicio de sesión exitoso", description: "Bienvenido de nuevo, Jefe." });
            router.push('/overview');
            router.refresh();
        } catch (err) {
            console.error("Login error:", err);
            setError('Ocurrió un error en el servidor.');
        }
    };

    const handleRegister = async () => {
        if (password !== confirmPassword) {
            setError('Las contraseñas no coinciden.');
            return;
        }
        if (password.length < 6) {
            setError('La contraseña debe tener al menos 6 caracteres.');
            return;
        }

        const result = await registerUser({
            username,
            password,
            location: { ciudad, barrio, edificio }
        });

        if (result.error) {
            setError(result.error);
        } else {
            toast({ title: "¡Registro exitoso!", description: `Bienvenido a Vendetta, ${username}.` });
            router.push('/overview');
            router.refresh();
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        startTransition(() => {
            if (isLoginView) {
                handleLogin();
            } else {
                handleRegister();
            }
        });
    };

    return (
        <Card className="w-full max-w-md bg-background/70 text-white border-white/20 backdrop-blur-md animate-fade-in">
            <CardHeader className="text-center">
                <CardTitle className="text-2xl font-bold tracking-wider">
                    {isLoginView ? 'INICIAR SESIÓN' : 'CREAR CUENTA'}
                </CardTitle>
                <CardDescription className="text-white/70">
                    {isLoginView ? 'Introduce tus credenciales para acceder a tu imperio.' : 'Únete a la familia y comienza tu legado.'}
                </CardDescription>
            </CardHeader>
            <form onSubmit={handleSubmit}>
                <CardContent className="space-y-4">
                    <div className="space-y-2">
                        <Label htmlFor="username">Usuario</Label>
                        <Input id="username" type="text" placeholder="Tu nombre de guerra" value={username} onChange={(e) => setUsername(e.target.value)} required disabled={isPending} />
                    </div>
                    <div className="space-y-2">
                        <Label htmlFor="password">Contraseña</Label>
                        <Input id="password" type="password" placeholder="Tu código secreto" value={password} onChange={(e) => setPassword(e.target.value)} required disabled={isPending} />
                    </div>
                    {!isLoginView && (
                         <div className="space-y-2 animate-fade-in">
                            <Label htmlFor="confirm-password">Confirmar Contraseña</Label>
                            <Input id="confirm-password" type="password" placeholder="Repite tu código secreto" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} required disabled={isPending} />
                        </div>
                    )}
                    {error && (
                        <Alert variant="destructive" className="bg-destructive/20 border-destructive/50 text-destructive-foreground">
                            <Terminal className="h-4 w-4" />
                            <AlertTitle>Error</AlertTitle>
                            <AlertDescription>{error}</AlertDescription>
                        </Alert>
                    )}
                </CardContent>
                <CardFooter className="flex-col gap-4">
                    <Button type="submit" className="w-full" disabled={isPending}>
                        {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                        {isLoginView ? 'Entrar' : 'Registrarse'}
                    </Button>
                    <p className="text-xs text-center text-white/60">
                        {isLoginView ? '¿No tienes una cuenta?' : '¿Ya eres parte de la familia?'}
                        <Button variant="link" type="button" size="sm" className="p-0 h-auto ml-1 text-accent" onClick={() => { setIsLoginView(!isLoginView); setError('') }}>
                             {isLoginView ? 'Regístrate aquí.' : 'Inicia sesión.'}
                        </Button>
                    </p>
                </CardFooter>
            </form>
        </Card>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { X, Hourglass, CheckCircle, Timer } from 'lucide-react';
import type { FullPropiedad } from '@/lib/data';
import { useRouter } from 'next/navigation';

function formatTime(totalSeconds: number) {
    if (totalSeconds < 0) totalSeconds = 0;
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = Math.floor(totalSeconds % 60);
    return [hours, minutes, seconds]
        .map(v => v.toString().padStart(2, '0'))
        .join(':');
}

type ConstructionQueueProps = {
    propiedad: FullPropiedad;
    allRooms: { id: string; nombre: string; }[];
};

export function ConstructionQueue({ propiedad, allRooms }: ConstructionQueueProps) {
    const router = useRouter();
    const [tiempoRestanteTotal, setTiempoRestanteTotal] = useState<number>(0);

    const construccionesEnCola = propiedad.colaConstruccion;

    useEffect(() => {
        if (construccionesEnCola.length === 0) {
            setTiempoRestanteTotal(0);
            return;
        };

        const ultimaConstruccionConFecha = [...construccionesEnCola].reverse().find(c => c.fechaFinalizacion);

        if (!ultimaConstruccionConFecha?.fechaFinalizacion) {
            setTiempoRestanteTotal(0);
            return;
        }

        const finTotal = new Date(ultimaConstruccionConFecha.fechaFinalizacion).getTime();

        const updateTimer = () => {
            const ahora = new Date().getTime();
            const diferencia = Math.floor((finTotal - ahora) / 1000);
            setTiempoRestanteTotal(diferencia > 0 ? diferencia : 0);
            if (diferencia < -1) { 
                router.refresh();
            }
        };

        updateTimer();
        const intervalId = setInterval(updateTimer, 1000);

        return () => clearInterval(intervalId);
    }, [construccionesEnCola, router]);

    if (construccionesEnCola.length === 0) {
        return null;
    }

    const construccionActiva = construccionesEnCola.find(c => c.fechaFinalizacion && new Date(c.fechaFinalizacion) > new Date());

    return (
        <Card className="mb-4">
            <CardHeader className="flex flex-row items-center justify-between">
                <CardTitle className="text-primary">Cola de Construcción ({propiedad.nombre})</CardTitle>
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <Timer className="h-4 w-4" />
                    <span>Total:</span>
                    <span className="font-mono font-bold text-foreground">{formatTime(tiempoRestanteTotal)}</span>
                </div>
            </CardHeader>
            <CardContent className="space-y-2">
                {construccionesEnCola.map((colaItem, index) => {
                    const roomConfig = allRooms.find(r => r.id === colaItem.habitacionId);
                    const esActiva = colaItem.id === construccionActiva?.id;
                    return (
                         <div key={colaItem.id} className={`flex items-center justify-between p-3 rounded-lg ${esActiva ? 'bg-muted/50' : 'bg-muted/20'}`}>
                            <div className="flex items-center gap-3">
                                {esActiva ? <CheckCircle className="h-5 w-5 text-green-500 animate-pulse" /> : <Hourglass className="h-5 w-5 text-amber-500" />}
                                <p className="font-semibold">
                                    {index + 1}. {roomConfig?.nombre || 'Habitación'} Nivel {colaItem.nivelDestino}
                                </p>
                            </div>
                            <div className="flex items-center gap-4">
                                <span className="font-mono text-sm font-bold text-primary">
                                    {formatTime(colaItem.duracion)}
                                </span>
                                <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-destructive">
                                   <X className="h-5 w-5" />
                                   <span className="sr-only">Cancelar</span>
                                </Button>
                            </div>
                        </div>
                    );
                })}
            </CardContent>
        </Card>
    );
}

'use client';

import type { ColaConstruccion } from "@prisma/client";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

type ConstructionStatusProps = {
    constructions: (ColaConstruccion & { propiedadNombre: string })[];
    totalSlots: number;
    allRooms: { id: string; nombre: string; }[];
};

function formatTime(totalSeconds: number): string {
    if (totalSeconds < 0) totalSeconds = 0;
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = Math.floor(totalSeconds % 60);
    return [hours, minutes, seconds]
        .map(v => v.toString().padStart(2, '0'))
        .join(':');
}

function CountdownTimer({ label, endDate, onFinish }: {label: string, endDate: string, onFinish: () => void}) {
    const [timeLeft, setTimeLeft] = useState('');

    useEffect(() => {
        const end = new Date(endDate).getTime();
        const intervalId = setInterval(() => {
            const now = new Date().getTime();
            const difference = Math.floor((end - now) / 1000);

            if (difference < -1) { // 1 second grace period
                setTimeLeft('00:00:00');
                clearInterval(intervalId);
                onFinish();
            } else {
                setTimeLeft(formatTime(difference));
            }
        }, 1000);

        const now = new Date().getTime();
        const difference = Math.floor((end - now) / 1000);
        setTimeLeft(formatTime(difference > 0 ? difference : 0));

        return () => clearInterval(intervalId);
    }, [endDate, onFinish]);

    return (
        <div className="flex justify-between items-center text-sm">
            <span>{label}</span>
            <span className="font-mono text-accent">{timeLeft}</span>
        </div>
    );
}

export function ConstructionStatus({ constructions, totalSlots, allRooms }: ConstructionStatusProps) {
    const router = useRouter();

    const handleRefresh = () => {
        router.refresh();
    };

    return (
        <div className="space-y-1">
            <div className="bg-primary text-primary-foreground px-4 py-1.5 rounded-t-md flex justify-between items-center font-bold mt-2">
                <span>HABITACIONES EN CONSTRUCCIÓN</span>
                <span>({constructions.length}/{totalSlots})</span>
            </div>
            <div className="bg-card text-card-foreground px-4 py-3 rounded-b-md space-y-2">
                {constructions.length > 0 ? (
                    constructions.map(queueItem => {
                        const room = allRooms.find(r => r.id === queueItem.habitacionId);
                        if (!room || !queueItem.fechaFinalizacion) return null;
                        return (
                             <CountdownTimer 
                                key={queueItem.id}
                                label={`${queueItem.propiedadNombre}: ${room.nombre} (Nvl ${queueItem.nivelDestino})`}
                                endDate={new Date(queueItem.fechaFinalizacion).toISOString()}
                                onFinish={handleRefresh}
                             />
                        )
                    })
                ) : (
                    <p className="text-muted-foreground text-center text-sm">No hay construcciones en cola.</p>
                )}
            </div>
        </div>
    );
}

