interface SimulatorViewProps {
    user: UserWithProgress;
    troopConfigs: ConfiguracionTropa[];
    trainingConfigs: ConfiguracionEntrenamiento[];
    defenseConfigs: ConfiguracionHabitacion[];
}

interface SimulatorColumnState {
    troops: Record<string, number>;
    trainings: Record<string, number>;
    defenses: Record<string, number>;
    buildingsLevel: number;
    propertyCount: number;
}

const initialColumnState: SimulatorColumnState = {
    troops: {},
    trainings: {},
    defenses: {},
    buildingsLevel: 1,
    propertyCount: 1,
};

const Section = ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div>
        <h3 className="text-lg font-semibold mb-2 text-primary">{title}</h3>
        <div className="space-y-2">{children}</div>
    </div>
);

const InputRow = ({ label, value, onChange }: { label: string; value: number; onChange: (value: number) => void }) => {
    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        onChange(parseInt(val, 10) || 0);
    };

    return (
        <div className="flex items-center justify-between">
            <Label htmlFor={label} className="text-sm truncate pr-2">{label}</Label>
            <Input
                id={label}
                type="number"
                min="0"
                value={value || ''}
                onChange={handleInputChange}
                placeholder="0"
                className="w-24 h-8 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
            />
        </div>
    );
};

function formatNumber(num: number): string {
    if(num === undefined || num === null) return "0";
    return num.toLocaleString('de-DE');
}

function SimulatorColumn({
    title,
    state,
    setState,
    troopConfigs,
    trainingConfigs,
    defenseConfigs,
    onLoadData,
    isDefender = false,
}: {
    title: string;
    state: SimulatorColumnState;
    setState: React.Dispatch<React.SetStateAction<SimulatorColumnState>>;
    troopConfigs: ConfiguracionTropa[];
    trainingConfigs: ConfiguracionEntrenamiento[];
    defenseConfigs: ConfiguracionHabitacion[];
    onLoadData: () => void;
    isDefender?: boolean;
}) {

    const handleStateChange = (
        section: keyof Omit<SimulatorColumnState, 'buildingsLevel' | 'propertyCount'>,
        id: string,
        value: number
    ) => {
        setState(prev => ({
            ...prev,
            [section]: {
                ...prev[section],
                [id]: value
            }
        }));
    };

     const handleGeneralValueChange = (field: 'buildingsLevel' | 'propertyCount', value: number) => {
         setState(prev => ({ ...prev, [field]: value }));
    }

    const handleClear = () => {
        setState(initialColumnState);
    }

    return (
        <Card>
            <CardHeader className="flex-row items-center justify-between">
                <CardTitle>{title}</CardTitle>
                <div className="flex items-center gap-2">
                     <Button variant="outline" size="sm" onClick={onLoadData}>
                        <Upload className="mr-2 h-4 w-4" />
                        Cargar mis datos
                    </Button>
                    <Button variant="ghost" size="icon" onClick={handleClear} className="h-8 w-8">
                        <Trash2 className="h-4 w-4" />
                        <span className="sr-only">Limpiar {title}</span>
                    </Button>
                </div>
            </CardHeader>
            <CardContent className="space-y-4">
                 <ScrollArea className="h-96 pr-4">
                    <div className="space-y-4">
                        <Section title="Tropas">
                            {troopConfigs.map(t => (
                                <InputRow
                                    key={`${title}-troop-${t.id}`}
                                    label={t.nombre}
                                    value={state.troops[t.id] || 0}
                                    onChange={(val) => handleStateChange('troops', t.id, val)}
                                />
                            ))}
                        </Section>
                        <Separator />
                        {isDefender && (
                            <>
                                <Section title="Defensas">
                                    {defenseConfigs.map(d => (
                                        <InputRow
                                            key={`${title}-defense-${d.id}`}
                                            label={d.nombre}
                                            value={state.defenses[d.id] || 0}
                                            onChange={(val) => handleStateChange('defenses', d.id, val)}
                                        />
                                    ))}</Section>
                                <Separator />
                            </>
                        )}
                        <Section title="Entrenamientos">
                            {trainingConfigs.map(t => (
                                <InputRow
                                    key={`${title}-training-${t.id}`}
                                    label={t.nombre}
                                    value={state.trainings[t.id] || 0}
                                    onChange={(val) => handleStateChange('trainings', t.id, val)}
                                />
                            ))}
                        </Section>

                        <Separator />
                        <Section title="General">
                             <InputRow
                                label="Nº Propiedades"
                                value={state.propertyCount}
                                onChange={(val) => handleGeneralValueChange('propertyCount', val)}
                            />
                            {isDefender && (
                                <InputRow
                                    label="Nivel Edificios (Defensa)"
                                    value={state.buildingsLevel}
                                    onChange={(val) => handleGeneralValueChange('buildingsLevel', val)}
                                />
                            )}
                        </Section>
                    </div>
                </ScrollArea>
            </CardContent>
        </Card>
    )
}

export function SimulatorView({ user, troopConfigs, trainingConfigs, defenseConfigs }: SimulatorViewProps) {
    const { selectedProperty } = useProperty();
    const [isPending, startTransition] = useTransition();
    const [attackerState, setAttackerState] = useState<SimulatorColumnState>(initialColumnState);
    const [defenderState, setDefenderState] = useState<SimulatorColumnState>(initialColumnState);
    const [battleReport, setBattleReport] = useState<BattleReport | null>(null);

    const formatSimulationInput = (state: SimulatorColumnState): SimulationInput => {
        return {
            troops: Object.entries(state.troops).filter(([,qty]) => qty > 0).map(([id, quantity]) => ({ id, quantity })),
            trainings: Object.entries(state.trainings).filter(([,lvl]) => lvl > 0).map(([id, level]) => ({ id, level })),
            defenses: Object.entries(state.defenses).filter(([,lvl]) => lvl > 0).map(([id, level]) => ({ id, level })),
            buildingsLevel: state.buildingsLevel,
            propertyCount: state.propertyCount
        };
    };

    const handleLoadUserData = (column: 'attacker' | 'defender') => {
        if (!selectedProperty) return;

        const troops = Object.fromEntries(
            selectedProperty.TropaUsuario.map(t => [t.configuracionTropaId, t.cantidad])
        );

        const trainings = Object.fromEntries(
            user.entrenamientos.map(t => [t.configuracionEntrenamientoId, t.nivel])
        );

        const defenses = Object.fromEntries(
            selectedProperty.habitaciones.filter(h => defenseConfigs.some(dc => dc.id === h.configuracionHabitacionId))
            .map(h => [h.configuracionHabitacionId, h.nivel])
        );

        const newState: SimulatorColumnState = {
            troops,
            trainings,
            defenses: column === 'defender' ? defenses : {},
            buildingsLevel: 1, // You might want to calculate an average level or set a default
            propertyCount: user.propiedades.length || 1,
        };

        if (column === 'attacker') {
            setAttackerState(newState);
        } else {
            setDefenderState(newState);
        }
    }


    const handleSimulate = () => {
        const attackerInput = formatSimulationInput(attackerState);
        const defenderInput = formatSimulationInput(defenderState);

        startTransition(async () => {
            const report = await runBattleSimulation(attackerInput, defenderInput);
            setBattleReport(report);
        });
    };

    const handleResetAll = () => {
        setAttackerState(initialColumnState);
        setDefenderState(initialColumnState);
        setBattleReport(null);
    }

    return (
        <div>
            <div className="flex flex-wrap items-center justify-between mb-4 gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight">Simulador de Batalla</h2>
                    <p className="text-muted-foreground">
                        Calcula los resultados de posibles enfrentamientos.
                    </p>
                </div>
                 <Button onClick={handleResetAll} variant="outline">
                    <Trash2 className="mr-2 h-4 w-4" />
                    Reiniciar Simulador
                </Button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <SimulatorColumn 
                    title="Atacante"
                    state={attackerState}
                    setState={setAttackerState}
                    troopConfigs={troopConfigs}
                    trainingConfigs={trainingConfigs}
                    defenseConfigs={defenseConfigs}
                    onLoadData={() => handleLoadUserData('attacker')}
                />
                <SimulatorColumn 
                    title="Defensor"
                    state={defenderState}
                    setState={setDefenderState}
                    troopConfigs={troopConfigs}
                    trainingConfigs={trainingConfigs}
                    defenseConfigs={defenseConfigs}
                    isDefender
                    onLoadData={() => handleLoadUserData('defender')}
                />
            </div>
            <div className="mt-6">
                <Button onClick={handleSimulate} disabled={isPending} className="w-full">
                    {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                    Simular Batalla
                </Button>
            </div>

            {battleReport && (
                 <Dialog open={!!battleReport} onOpenChange={(isOpen) => !isOpen && setBattleReport(null)}>
                    <DialogContent className="max-w-4xl bg-black/80 border-primary text-white">
                        <DialogHeader>
                            <DialogTitle className="text-2xl text-center text-primary tracking-widest font-heading">
                                INFORME DE BATALLA
                            </DialogTitle>
                        </DialogHeader>
                        <ScrollArea className="h-[70vh]">
                            <div className="space-y-4 pr-4">
                                {battleReport.rounds.map(round => (
                                    <div key={round.round} className="space-y-2">
                                        <div className="bg-primary/80 text-primary-foreground text-center font-bold font-heading py-1">
                                            RONDA DE BATALLA {round.round}
                                        </div>
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                            {/* Columna Atacante */}
                                            <div>
                                                <h4 className='font-bold text-center mb-1 font-heading'>Atacante</h4>
                                                <Table>
                                                    <TableHeader>
                                                        <TableRow className="border-b-primary/50">
                                                            <TableHead className="text-white">Tropa</TableHead>
                                                            <TableHead className="text-right text-white">Cant.</TableHead>
                                                            <TableHead className="text-right text-red-500">Pérdidas</TableHead>
                                                        </TableRow>
                                                    </TableHeader>
                                                    <TableBody>
                                                        {round.attacker.troops.map(t => (
                                                            <TableRow key={t.id} className="border-b-primary/20">
                                                                <TableCell>{t.nombre}</TableCell>
                                                                <TableCell className="text-right">{formatNumber(t.initialQuantity)}</TableCell>
                                                                <TableCell className="text-right text-red-500">{formatNumber(t.lostQuantity)}</TableCell>
                                                            </TableRow>
                                                        ))}
                                                    </TableBody>
                                                </Table>
                                            </div>
                                             {/* Columna Defensor */}
                                            <div>
                                                 <h4 className='font-bold text-center mb-1 font-heading'>Defensor</h4>
                                                <Table>
                                                    <TableHeader>
                                                        <TableRow className="border-b-primary/50">
                                                            <TableHead className="text-white">Tropa</TableHead>
                                                            <TableHead className="text-right text-white">Cant.</TableHead>
                                                            <TableHead className="text-right text-red-500">Pérdidas</TableHead>
                                                        </TableRow>
                                                    </TableHeader>
                                                    <TableBody>
                                                        {round.defender.troops.map(t => (
                                                            <TableRow key={t.id} className="border-b-primary/20">
                                                                <TableCell>{t.nombre}</TableCell>
                                                                <TableCell className="text-right">{formatNumber(t.initialQuantity)}</TableCell>
                                                                <TableCell className="text-right text-red-500">{formatNumber(t.lostQuantity)}</TableCell>
                                                            </TableRow>
                                                        ))}
                                                    </TableBody>
                                                </Table>
                                            </div>
                                        </div>

                                        <div className="bg-primary/80 text-primary-foreground text-center font-bold font-heading py-1 mt-2">
                                            ESTADO RONDA {round.round}
                                        </div>
                                        <div className="grid grid-cols-2 gap-x-4 p-2 text-sm font-mono">
                                             <div><span className="font-bold">Ataque Atacante:</span> {formatNumber(round.attacker.totalAttack)}</div>
                                             <div className="text-right"><span className="font-bold">Defensa Defensor:</span> {formatNumber(round.defender.totalDefense)}</div>
                                             <div><span className="font-bold">Ataque Defensor:</span> {formatNumber(round.defender.totalAttack)}</div>
                                             <div className="text-right"><span className="font-bold">Defensa Atacante:</span> {formatNumber(round.attacker.totalDefense)}</div>
                                        </div>
                                    </div>
                                ))}

                                {battleReport.finalMessage && <p className="text-center font-bold text-lg pt-4">{battleReport.finalMessage}</p>}

                                <div className="bg-primary/80 text-primary-foreground text-center font-bold font-heading py-1 mt-4">
                                    ESTADÍSTICAS FINALES
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-3 text-center text-sm p-2">
                                    <div className='font-bold'>-</div>
                                    <div className='font-bold'>Atacante</div>
                                    <div className='font-bold'>Defensor</div>
                                </div>
                                <Table>
                                    <TableBody>
                                        <TableRow className="border-none"><TableCell>Tropas perdidas</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.attacker.troopsLost)}</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.defender.troopsLost)}</TableCell></TableRow>
                                        <TableRow className="border-none"><TableCell>Puntos perdidos</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.attacker.pointsLost)}</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.defender.pointsLost)}</TableCell></TableRow>
                                        <TableRow className="border-none"><TableCell>Armas perdido</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.attacker.resourcesLost.armas)}</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.defender.resourcesLost.armas)}</TableCell></TableRow>
                                        <TableRow className="border-none"><TableCell>Municion perdido</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.attacker.resourcesLost.municion)}</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.defender.resourcesLost.municion)}</TableCell></TableRow>
                                        <TableRow className="border-none"><TableCell>Dolares perdido</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.attacker.resourcesLost.dolares)}</TableCell><TableCell className="text-right text-red-400">{formatNumber(battleReport.finalStats.defender.resourcesLost.dolares)}</TableCell></TableRow>
                                    </TableBody>
                                </Table>

                            </div>
                        </ScrollArea>
                        <DialogFooter>
                            <DialogClose asChild>
                                <Button className="w-full bg-red-800 hover:bg-red-700 text-white">Cerrar</Button>
                            </DialogClose>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            )}
        </div>
    );
}

'use client';

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { Trophy } from "lucide-react";

export interface StatItem {
    id: string;
    name: string;
    userValue: number;
    maxValue: number;
}

interface StatCategoryCardProps {
    title: string;
    items: StatItem[];
}

function formatNumber(num: number): string {
    return num.toLocaleString('de-DE');
}

export function StatCategoryCard({ title, items }: StatCategoryCardProps) {
    return (
        <Card>
            <CardHeader>
                <CardTitle>{title}</CardTitle>
            </CardHeader>
            <CardContent>
                <ScrollArea className="h-96">
                    <div className="space-y-6 pr-4">
                        {items.map(item => {
                            const progressPercentage = item.maxValue > 0 ? (item.userValue / item.maxValue) * 100 : 0;
                            const isServerRecord = item.userValue > 0 && item.userValue === item.maxValue;
                            return (
                                <div key={item.id} className="space-y-1">
                                    <div className="flex justify-between items-baseline text-sm">
                                        <div className="flex items-center gap-2">
                                            {isServerRecord && (
                                                <TooltipProvider>
                                                    <Tooltip>
                                                        <TooltipTrigger>
                                                            <Trophy className="h-4 w-4 text-amber-400 animate-pulse" />
                                                        </TooltipTrigger>
                                                        <TooltipContent>
                                                            <p>Récord del Servidor</p>
                                                        </TooltipContent>
                                                    </Tooltip>
                                                </TooltipProvider>
                                            )}
                                            <span className="font-medium truncate pr-2">{item.name}</span>
                                        </div>
                                        <div className="flex items-baseline gap-2">
                                            <span className="font-bold text-primary">{formatNumber(item.userValue)}</span>
                                            <span className="text-xs text-muted-foreground">/ {formatNumber(item.maxValue)}</span>
                                        </div>
                                    </div>
                                    <Progress value={progressPercentage} className="h-2" />
                                </div>
                            )
                        })}
                    </div>
                </ScrollArea>
            </CardContent>
        </Card>
    );
}

'use client';

import { Card } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

interface StatTableCardProps {
    title: string;
    headers: string[];
    data: (string | number)[][];
}

function formatNumber(value: string | number) {
    if (typeof value === 'number') {
        return value.toLocaleString('de-DE');
    }
    return value;
}

export function StatTableCard({ title, headers, data }: StatTableCardProps) {
    return (
        <Card className="overflow-hidden">
            <div className="bg-primary text-primary-foreground p-4">
                <h3 className="font-heading text-xl tracking-wider">{title}</h3>
            </div>
            <div className="bg-card">
                 <Table>
                    <TableHeader>
                        <TableRow className="border-b-white/10 hover:bg-white/5">
                            {headers.map((header, index) => (
                                <TableHead key={index} className={`font-bold text-white/90 ${index > 0 ? 'text-right' : ''}`}>
                                    {header}
                                </TableHead>
                            ))}
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {data.map((row, rowIndex) => (
                             <TableRow key={rowIndex} className="border-b-white/10 hover:bg-white/5">
                                {row.map((cell, cellIndex) => (
                                    <TableCell key={cellIndex} className={`${cellIndex > 0 ? 'text-right' : 'font-medium'}`}>
                                        {formatNumber(cell)}
                                    </TableCell>
                                ))}
                            </TableRow>
                        ))}
                    </TableBody>
                </Table>
            </div>
        </Card>
    );
}

'use client';

import { ConfiguracionHabitacion, ConfiguracionTropa, ConfiguracionEntrenamiento, HabitacionUsuario, EntrenamientoUsuario } from "@prisma/client";
import { UserWithProgress } from "@/lib/data";
import { StatTableCard } from "./stat-table-card";

interface TroopStat {
    userId: string;
    total: number;
    configuracionTropaId: string;
}

interface ResourceStat {
    name: string;
    maxValue: number;
}

interface StatisticsViewProps {
    currentUser: UserWithProgress;
    allRoomConfigs: ConfiguracionHabitacion[];
    allTrainingConfigs: ConfiguracionEntrenamiento[];
    allTroopConfigs: ConfiguracionTropa[];
    roomStats: HabitacionUsuario[];
    trainingStats: EntrenamientoUsuario[];
    troopStats: TroopStat[];
    resourceStats: ResourceStat[];
}

export function StatisticsView({
    currentUser,
    allRoomConfigs,
    allTrainingConfigs,
    allTroopConfigs,
    roomStats,
    trainingStats,
    troopStats,
    resourceStats
}: StatisticsViewProps) {

    // Process room stats
    const maxRoomLevels = new Map<string, number>();
    roomStats.forEach(stat => {
        const currentMax = maxRoomLevels.get(stat.configuracionHabitacionId) || 0;
        if (stat.nivel > currentMax) {
            maxRoomLevels.set(stat.configuracionHabitacionId, stat.nivel);
        }
    });

    const currentUserRoomLevels = new Map<string, number>();
    currentUser.propiedades.forEach(p => {
        p.habitaciones.forEach(h => {
            const currentLevel = currentUserRoomLevels.get(h.configuracionHabitacionId) || 0;
            if (h.nivel > currentLevel) {
                 currentUserRoomLevels.set(h.configuracionHabitacionId, h.nivel);
            }
        });
    });

    const roomStatData = allRoomConfigs.map(config => ([
        config.nombre,
        currentUserRoomLevels.get(config.id) || 0,
        maxRoomLevels.get(config.id) || 0,
    ]));

    // Process training stats
    const maxTrainingLevels = new Map<string, number>();
    trainingStats.forEach(stat => {
        const currentMax = maxTrainingLevels.get(stat.configuracionEntrenamientoId) || 0;
        if (stat.nivel > currentMax) {
            maxTrainingLevels.set(stat.configuracionEntrenamientoId, stat.nivel);
        }
    });
    const currentUserTrainingLevels = new Map(currentUser.entrenamientos.map(t => [t.configuracionEntrenamientoId, t.nivel]));

    const trainingStatData = allTrainingConfigs.map(config => ([
        config.nombre,
        currentUserTrainingLevels.get(config.id) || 0,
        maxTrainingLevels.get(config.id) || 0,
    ]));

    // Process troop stats
    const maxTroopCounts = new Map<string, number>();
    troopStats.forEach(stat => {
        const currentMax = maxTroopCounts.get(stat.configuracionTropaId) || 0;
        if (stat.total > currentMax) {
            maxTroopCounts.set(stat.configuracionTropaId, stat.total);
        }
    });

    const currentUserTroopCounts = new Map<string, number>();
    troopStats.filter(t => t.userId === currentUser.id).forEach(t => {
        currentUserTroopCounts.set(t.configuracionTropaId, t.total);
    });

    const troopStatData = allTroopConfigs.map(config => ([
        config.nombre,
        currentUserTroopCounts.get(config.id) || 0,
        maxTroopCounts.get(config.id) || 0,
    ]));

    const resourceStatData = resourceStats.map(stat => ([
        stat.name,
        stat.maxValue
    ]));

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight">Estadísticas Globales</h2>
                    <p className="text-muted-foreground">
                        Compara tu progreso con los mejores jugadores del servidor.
                    </p>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <StatTableCard title="ESTADÍSTICAS DE RECURSOS" headers={['Recurso', 'Máximo por edificio']} data={resourceStatData} />
                <StatTableCard title="ESTADÍSTICAS DE HABITACIONES" headers={['Habitación', 'Mi Nivel', 'Nivel Máximo']} data={roomStatData} />
                <StatTableCard title="ESTADÍSTICAS DE ENTRENAMIENTOS" headers={['Entrenamiento', 'Mi Nivel', 'Nivel Máximo']} data={trainingStatData} />
                <StatTableCard title="ESTADÍSTICAS DE TROPAS" headers={['Tropa', 'Mis Unidades', 'Unidades Máximas']} data={troopStatData} />
            </div>
        </div>
    );
}

