'use server'

import { revalidatePath } from "next/cache";
import prisma from "../prisma/prisma";
import { getSessionUser } from "../auth";
import { getPropertyOwner, getTroopConfigurations } from "../data";
import { calcularDistancia, calcularDuracionViaje, calcularVelocidadFlota } from "../formulas/mission-formulas";

interface MissionInput {
    origenPropiedadId: string;
    coordinates: {
        ciudad: number;
        barrio: number;
        edificio: number;
    },
    tropas: { id: string, cantidad: number }[];
    tipo: string;
}

const MISIONES_SIN_RETORNO = ['OCUPAR'];

export async function enviarMision(input: MissionInput) {
    const user = await getSessionUser();
    if (!user) {
        return { error: "Usuario no autenticado." };
    }

    const { origenPropiedadId, coordinates, tropas, tipo } = input;
    const origenPropiedad = user.propiedades.find(p => p.id === origenPropiedadId);

    if (!origenPropiedad) {
        return { error: "Propiedad de origen no encontrada." };
    }

    if (!coordinates.ciudad || !coordinates.barrio || !coordinates.edificio) {
        return { error: "Coordenadas incompletas." };
    }
     if (tropas.length === 0 || tropas.every(t => t.cantidad === 0)) {
        return { error: "Debes seleccionar al menos una tropa." };
    }

    const tropasPropiedadMap = new Map(origenPropiedad.TropaUsuario.map(t => [t.configuracionTropaId, t.cantidad]));

    for (const tropa of tropas) {
        if ((tropasPropiedadMap.get(tropa.id) || 0) < tropa.cantidad) {
            return { error: `No tienes suficientes unidades de una de las tropas seleccionadas en ${origenPropiedad.nombre}.` };
        }
    }

    // Calcular distancia y duración con las nuevas fórmulas
    const troopConfigs = await getTroopConfigurations();
    const troopConfigsMap = new Map(troopConfigs.map(t => [t.id, t]));

    const velocidadFlota = await calcularVelocidadFlota(tropas, troopConfigsMap);
    const distancia = calcularDistancia(origenPropiedad, coordinates);
    const duracionViaje = calcularDuracionViaje(distancia, velocidadFlota);

    const fechaInicio = new Date();
    const fechaLlegada = new Date(fechaInicio.getTime() + duracionViaje * 1000);
    const requiereRetorno = !MISIONES_SIN_RETORNO.includes(tipo);
    const fechaRegreso = requiereRetorno ? new Date(fechaLlegada.getTime() + duracionViaje * 1000) : null;


    if (tipo === 'OCUPAR') {
        const targetOwner = await getPropertyOwner(coordinates);
        if (targetOwner) {
            return { error: "No puedes ocupar una propiedad que ya tiene dueño." };
        }

        const tropaOcupacion = tropas.find(t => t.id === 'ocupacion');
        if (!tropaOcupacion || tropaOcupacion.cantidad === 0) {
            return { error: "Necesitas enviar al menos una Tropa de Ocupación para esta misión." };
        }

        try {
            await prisma.$transaction(async (tx) => {
                const allRoomConfigs = await tx.configuracionHabitacion.findMany();
                await tx.propiedad.create({
                    data: {
                        userId: user.id,
                        nombre: `Colonia en ${coordinates.ciudad}:${coordinates.barrio}`,
                        ciudad: coordinates.ciudad,
                        barrio: coordinates.barrio,
                        edificio: coordinates.edificio,
                        armas: 10000,
                        municion: 10000,
                        alcohol: 10000,
                        dolares: 10000,
                        habitaciones: {
                            create: allRoomConfigs.map(config => ({
                                configuracionHabitacionId: config.id,
                                nivel: 1
                            }))
                        }
                    }
                });

                await tx.tropaUsuario.update({
                    where: { propiedadId_configuracionTropaId: { propiedadId: origenPropiedadId, configuracionTropaId: 'ocupacion' } },
                    data: { cantidad: { decrement: tropaOcupacion.cantidad } }
                });
            });

            revalidatePath('/overview');
            revalidatePath('/map');
            return { success: `¡Has ocupado exitosamente la propiedad en ${coordinates.ciudad}:${coordinates.barrio}:${coordinates.edificio}!` };

        } catch (error) {
            console.error(error);
            return { error: "Error al crear la nueva propiedad." };
        }
    }

    try {
        await prisma.$transaction(async (tx) => {
            await tx.colaMisiones.create({
                data: {
                    userId: user.id,
                    propiedadOrigenId: origenPropiedadId,
                    tipoMision: tipo,
                    tropas: JSON.stringify(tropas),
                    origenCiudad: origenPropiedad.ciudad,
                    origenBarrio: origenPropiedad.barrio,
                    origenEdificio: origenPropiedad.edificio,
                    destinoCiudad: coordinates.ciudad,
                    destinoBarrio: coordinates.barrio,
                    destinoEdificio: coordinates.edificio,
                    fechaInicio: fechaInicio,
                    fechaLlegada: fechaLlegada,
                    fechaRegreso: fechaRegreso,
                    velocidadFlota,
                    duracionViaje,
                }
            });

            for (const t of tropas) {
                if (t.cantidad > 0) {
                    await tx.tropaUsuario.update({
                        where: { propiedadId_configuracionTropaId: { propiedadId: origenPropiedadId, configuracionTropaId: t.id } },
                        data: { cantidad: { decrement: t.cantidad } }
                    });
                }
            }
        });

    } catch (error) {
        console.error("Error al crear la misión:", error);
        return { error: "No se pudo enviar la misión." };
    }

    revalidatePath('/missions');
    revalidatePath('/overview');

    return { success: `Misión de ${tipo} enviada a ${coordinates.ciudad}:${coordinates.barrio}:${coordinates.edificio}.` };
}

'use server';

import { revalidatePath } from "next/cache";
import prisma from "../prisma/prisma";
import { getSessionUser } from "../auth";
import { FullConfiguracionHabitacion } from "../data";
import { calcularCostosNivel, calcularTiempoConstruccion } from "../formulas/room-formulas";

export async function iniciarAmpliacion(propiedadId: string, habitacionId: string) {
    const user = await getSessionUser();

    if (!user) {
      return { error: 'Usuario no autenticado.' };
    }

    const propiedadActual = user.propiedades.find(p => p.id === propiedadId);
    if (!propiedadActual) {
        return { error: 'Propiedad no encontrada para este usuario.' };
    }

    const construccionesEnCola = propiedadActual.colaConstruccion;

    if (construccionesEnCola.length >= 5) {
        return { error: 'La cola de construcción está llena (máximo 5).' };
    }

    const habitacionUsuario = propiedadActual.habitaciones.find(h => h.configuracionHabitacionId === habitacionId);

    if (!habitacionUsuario) {
         return { error: 'Configuración de habitación de usuario no encontrada.' };
    }

    const config = habitacionUsuario.configuracion;
    if (!config) {
        return { error: 'Configuración de la habitación no encontrada.'}
    }

    const nivelBase = habitacionUsuario.nivel;
    const mejorasEnCola = construccionesEnCola.filter(c => c.habitacionId === habitacionId).length;
    const nivelSiguiente = nivelBase + mejorasEnCola + 1;

    const nivelOficinaJefe = propiedadActual.habitaciones.find(h => h.configuracionHabitacionId === 'oficina_del_jefe')?.nivel || 1;

    const costos = calcularCostosNivel(nivelSiguiente, config as FullConfiguracionHabitacion);

    if (
      propiedadActual.armas < costos.armas ||
      propiedadActual.municion < costos.municion ||
      propiedadActual.dolares < costos.dolares
    ) {
      return { error: 'No tienes suficientes recursos para esta ampliación.' };
    }

    const duracion = calcularTiempoConstruccion(nivelSiguiente, config, nivelOficinaJefe);

    // Encontrar la fecha de finalización de la última construcción en la cola para esta propiedad
    const ultimaConstruccion = await prisma.colaConstruccion.findFirst({
        where: { propiedadId: propiedadId },
        orderBy: { fechaFinalizacion: 'desc' },
    });

    const ahora = new Date();
    let fechaInicio: Date;

    if (ultimaConstruccion && ultimaConstruccion.fechaFinalizacion) {
        // La nueva construcción empieza 1 segundo después de la anterior
        fechaInicio = new Date(ultimaConstruccion.fechaFinalizacion.getTime() + 1000);
    } else {
        // Si no hay nada en la cola, empieza ahora
        fechaInicio = ahora;
    }

    const fechaFinalizacion = new Date(fechaInicio.getTime() + duracion * 1000);

    try {
      await prisma.$transaction([
        prisma.propiedad.update({
          where: { id: propiedadId },
          data: {
            armas: { decrement: costos.armas },
            municion: { decrement: costos.municion },
            dolares: { decrement: costos.dolares },
          },
        }),
        prisma.colaConstruccion.create({
            data: {
                propiedadId: propiedadId,
                habitacionId: habitacionId,
                nivelDestino: nivelSiguiente,
                duracion: duracion,
                fechaInicio: fechaInicio,
                fechaFinalizacion: fechaFinalizacion,
            }
        })
      ]);

      revalidatePath('/rooms');
      revalidatePath('/overview'); 
      revalidatePath('/(dashboard)/layout', 'layout');

      return { success: `¡${config.nombre} añadido a la cola de construcción!` };
    } catch (error) {
      console.error('Error durante la transacción de ampliación:', error);
      return { error: 'Ocurrió un error en el servidor al intentar ampliar.' };
    }
}

import type { UserWithProgress } from "../data";

export function calcularPuntosHabitaciones(user: UserWithProgress): number {
  if (!user.propiedades || user.propiedades.length === 0) return 0;

  return user.propiedades.reduce((totalPropiedades, propiedad) => {
    const puntosPropiedad = propiedad.habitaciones.reduce((totalHabitaciones, habitacion) => {
      const puntos = habitacion.configuracion.puntos * habitacion.nivel;
      return totalHabitaciones + puntos;
    }, 0);
    return totalPropiedades + puntosPropiedad;
  }, 0);
}

export function calcularPuntosTropas(user: UserWithProgress): number {
  if (!user.propiedades) return 0;

  return user.propiedades.reduce((totalPropiedades, propiedad) => {
    const puntosPropiedad = propiedad.TropaUsuario.reduce((totalTropas, tropa) => {
      const puntos = tropa.configuracion.puntos * tropa.cantidad;
      return totalTropas + puntos;
    }, 0);
    return totalPropiedades + puntosPropiedad;
  }, 0);
}

export function calcularPuntosEntrenamientos(user: UserWithProgress): number {
  if (!user.entrenamientos) return 0;

  return user.entrenamientos.reduce((total, entrenamiento) => {
    const puntos = entrenamiento.configuracion.puntos * entrenamiento.nivel;
    return total + puntos;
  }, 0);
}

'use server';

import { getTrainingConfigurations, getTroopConfigurations } from '../data';
import { calcularPoderAtaque } from '../formulas/score-formulas';
import { calcularStatsTropaConBonus } from '../formulas/troop-formulas';
import type { ConfiguracionTropa, TropaBonusContrincante } from '@prisma/client';

// --- INPUT TYPES ---
interface TroopData {
    id: string;
    quantity: number;
}

interface TrainingData {
    id: string;
    level: number;
}

interface DefenseData {
    id: string;
    level: number;
}

export interface SimulationInput {
    troops: TroopData[];
    trainings: TrainingData[];
    defenses: DefenseData[];
    buildingsLevel: number;
    propertyCount: number;
}

// --- BATTLE LOGIC INTERNAL TYPES ---
interface ArmyUnit {
    id: string;
    nombre: string;
    config: ConfiguracionTropa & { bonusContrincante: TropaBonusContrincante[] };
    quantity: number;
    attack: number;
    defense: number;
}

// --- OUTPUT REPORT TYPES ---
export interface RoundParticipantReport {
    troops: {
        id: string;
        nombre: string;
        initialQuantity: number;
        lostQuantity: number;
    }[];
    totalAttack: number;
    totalDefense: number;
}

export interface BattleRoundReport {
    round: number;
    attacker: RoundParticipantReport;
    defender: RoundParticipantReport;
}

interface ResourceCost {
    armas: number;
    municion: number;
    dolares: number;
}

export interface CombatStats {
    attacker: {
        troopsLost: number;
        pointsLost: number;
        resourcesLost: ResourceCost;
    };
    defender: {
        troopsLost: number;
        pointsLost: number;
        resourcesLost: ResourceCost;
    };
}
export interface BattleReport {
    winner: 'attacker' | 'defender' | 'draw';
    rounds: BattleRoundReport[];
    finalMessage: string;
    finalStats: CombatStats;
}


function calculateResourceLoss(lostTroops: ArmyUnit[], troopConfigsMap: Map<string, ConfiguracionTropa>): ResourceCost {
    return lostTroops.reduce((total, unit) => {
        const config = troopConfigsMap.get(unit.id);
        if(config) {
            total.armas += config.costoArmas * unit.quantity;
            total.municion += config.costoMunicion * unit.quantity;
            total.dolares += config.costoDolares * unit.quantity;
        }
        return total;
    }, { armas: 0, municion: 0, dolares: 0 });
}

export async function runBattleSimulation(attacker: SimulationInput, defender: SimulationInput): Promise<BattleReport> {
    const [troopConfigs, trainingConfigs] = await Promise.all([
        getTroopConfigurations(),
        getTrainingConfigurations()
    ]);
    const troopConfigsMap = new Map(troopConfigs.map(t => [t.id, t]));
    const trainingConfigsMap = new Map(trainingConfigs.map(t => [t.id, t]));

    const buildArmy = (simInput: SimulationInput): ArmyUnit[] => {
        const userTrainings = simInput.trainings.map(t => ({
            configuracionEntrenamientoId: t.id,
            nivel: t.level,
            configuracion: trainingConfigsMap.get(t.id)!
        }));

        return simInput.troops.map(troop => {
            const config = troopConfigsMap.get(troop.id);
            if (!config) return null;
            const { ataqueActual, defensaActual } = calcularStatsTropaConBonus(config, userTrainings as any);
            return {
                id: troop.id,
                nombre: config.nombre,
                config: config,
                quantity: troop.quantity,
                attack: ataqueActual,
                defense: defensaActual,
            };
        }).filter((u): u is ArmyUnit => u !== null && u.quantity > 0);
    };

    let attackerArmy = buildArmy(attacker);
    let defenderArmy = buildArmy(defender);

    const initialAttackerArmy = JSON.parse(JSON.stringify(attackerArmy));
    const initialDefenderArmy = JSON.parse(JSON.stringify(defenderArmy));

    const honorAtacante = attacker.trainings.find(t => t.id === 'honor')?.level || 0;
    const honorDefensor = defender.trainings.find(t => t.id === 'honor')?.level || 0;

    const poderAtaqueAtacante = await calcularPoderAtaque(attacker.propertyCount, honorAtacante);
    const poderAtaqueDefensor = await calcularPoderAtaque(defender.propertyCount, honorDefensor);

    const battleRounds: BattleRoundReport[] = [];
    let finalMessage = "";

    for (let i = 1; i <= 5; i++) {
        let attackerTroopCount = attackerArmy.reduce((sum, u) => sum + u.quantity, 0);
        let defenderTroopCount = defenderArmy.reduce((sum, u) => sum + u.quantity, 0);

        if (attackerTroopCount === 0 || defenderTroopCount === 0) break;

        const roundAttackerArmyBefore = JSON.parse(JSON.stringify(attackerArmy));
        const roundDefenderArmyBefore = JSON.parse(JSON.stringify(defenderArmy));
        const attackerLossesThisRound = new Map<string, number>();
        const defenderLossesThisRound = new Map<string, number>();

        let attackerTotalAttack = attackerArmy.reduce((sum, u) => sum + u.attack * u.quantity, 0) * (poderAtaqueAtacante / 100);
        let defenderTotalAttack = defenderArmy.reduce((sum, u) => sum + u.attack * u.quantity, 0) * (poderAtaqueDefensor / 100);
        let attackerTotalDefense = attackerArmy.reduce((sum, u) => sum + u.defense * u.quantity, 0) * (poderAtaqueAtacante / 100);
        let defenderTotalDefense = defenderArmy.reduce((sum, u) => sum + u.defense * u.quantity, 0) * (poderAtaqueDefensor / 100);

        const attackerLossRatio = defenderTotalAttack > attackerTotalDefense ? 1 : defenderTotalAttack / (attackerTotalDefense || 1);
        const defenderLossRatio = attackerTotalAttack > defenderTotalDefense ? 1 : attackerTotalAttack / (defenderTotalDefense || 1);

        attackerArmy.forEach(u => {
            const losses = Math.floor(u.quantity * attackerLossRatio);
            attackerLossesThisRound.set(u.id, (attackerLossesThisRound.get(u.id) || 0) + losses);
            u.quantity -= losses;
        });

        defenderArmy.forEach(u => {
            const losses = Math.floor(u.quantity * defenderLossRatio);
            defenderLossesThisRound.set(u.id, (defenderLossesThisRound.get(u.id) || 0) + losses);
            u.quantity -= losses;
        });

        battleRounds.push({
            round: i,
            attacker: {
                troops: roundAttackerArmyBefore.map((t: ArmyUnit) => ({
                    id: t.id,
                    nombre: t.nombre,
                    initialQuantity: t.quantity,
                    lostQuantity: attackerLossesThisRound.get(t.id) || 0,
                })),
                totalAttack: attackerTotalAttack,
                totalDefense: attackerTotalDefense
            },
            defender: {
                 troops: roundDefenderArmyBefore.map((t: ArmyUnit) => ({
                    id: t.id,
                    nombre: t.nombre,
                    initialQuantity: t.quantity,
                    lostQuantity: defenderLossesThisRound.get(t.id) || 0,
                })),
                totalAttack: defenderTotalAttack,
                totalDefense: defenderTotalDefense,
            },
        });
    }

    const finalAttackerTroops = new Map(attackerArmy.map(u => [u.id, u.quantity]));
    const finalDefenderTroops = new Map(defenderArmy.map(u => [u.id, u.quantity]));

    const totalAttackerLossesArray: ArmyUnit[] = initialAttackerArmy.map((u: ArmyUnit) => ({ ...u, quantity: u.quantity - (finalAttackerTroops.get(u.id) || 0)}));
    const totalDefenderLossesArray: ArmyUnit[] = initialDefenderArmy.map((u: ArmyUnit) => ({...u, quantity: u.quantity - (finalDefenderTroops.get(u.id) || 0)}));

    const finalStats: CombatStats = {
        attacker: {
            troopsLost: totalAttackerLossesArray.reduce((s, u) => s + u.quantity, 0),
            pointsLost: totalAttackerLossesArray.reduce((s, u) => s + (u.config.puntos || 0) * u.quantity, 0),
            resourcesLost: calculateResourceLoss(totalAttackerLossesArray, troopConfigsMap)
        },
        defender: {
            troopsLost: totalDefenderLossesArray.reduce((s, u) => s + u.quantity, 0),
            pointsLost: totalDefenderLossesArray.reduce((s, u) => s + (u.config.puntos || 0) * u.quantity, 0),
            resourcesLost: calculateResourceLoss(totalDefenderLossesArray, troopConfigsMap)
        }
    }

    const attackerHasTroops = attackerArmy.some(u => u.quantity > 0);
    const defenderHasTroops = defenderArmy.some(u => u.quantity > 0);

    let winner: 'attacker' | 'defender' | 'draw';
    if(attackerHasTroops && !defenderHasTroops) {
        winner = 'attacker';
        finalMessage = "El atacante ha ganado la batalla."
    } else if (!attackerHasTroops && defenderHasTroops) {
        winner = 'defender';
        finalMessage = "El defensor ha repelido el ataque."
    } else if (!attackerHasTroops && !defenderHasTroops) {
        winner = 'draw';
        finalMessage = "Aniquilación mutua. Nadie sobrevive."
    } else {
        winner = 'draw';
        finalMessage = "La batalla ha terminado en empate tras 5 rondas.";
    }

    return { winner, rounds: battleRounds, finalStats, finalMessage };
}

'use server';

import { loginSuperUserSession } from "../auth-super";
import prisma from "../prisma/prisma";

interface LoginInput {
    username: string;
    password?: string;
}

export async function loginSuperUser(credentials: LoginInput) {
    const { username, password } = credentials;

    const superUser = await prisma.superUser.findUnique({
        where: { username },
    });

    if (!superUser) {
        return { error: "Credenciales de superusuario incorrectas." };
    }

    // In a real app, hash and compare passwords securely.
    // For this project's security scope, we do a direct comparison.
    if (superUser.password !== password) {
        return { error: "Credenciales de superusuario incorrectas." };
    }

    await loginSuperUserSession();

    // The redirect will be handled by the page component after revalidation
    return { success: true };
}

'use server';

import { revalidatePath } from "next/cache";
import prisma from "../prisma/prisma";
import { getSessionUser } from "../auth";
import { getTrainingConfigurations } from "../data";
import { calcularCostosEntrenamiento, calcularTiempoEntrenamiento } from "../formulas/training-formulas";

export async function iniciarEntrenamiento(trainingId: string, propertyId: string) {
    const user = await getSessionUser();

    if (!user) {
      return { error: 'Usuario no autenticado.' };
    }

    const propiedadActual = user.propiedades.find(p => p.id === propertyId);
    if (!propiedadActual) {
        return { error: 'Propiedad no encontrada para este usuario.' };
    }

    const colaEntrenamientoUsuario = await prisma.colaEntrenamiento.findMany({ where: { userId: user.id } });

    if (colaEntrenamientoUsuario.some(c => c.propiedadId === propertyId)) {
        return { error: 'Ya hay un entrenamiento en curso en esta propiedad.' };
    }

    if (colaEntrenamientoUsuario.some(c => c.entrenamientoId === trainingId)) {
        return { error: 'Ya estás investigando este entrenamiento en otra propiedad.' };
    }

    const allTrainingConfigs = await getTrainingConfigurations();
    const config = allTrainingConfigs.find(c => c.id === trainingId);

    if (!config) {
        return { error: 'Configuración de entrenamiento no encontrada.'}
    }

    const userTraining = user.entrenamientos.find(t => t.configuracionEntrenamientoId === trainingId);

    const nivelActual = userTraining ? userTraining.nivel : 0;
    const nivelSiguiente = nivelActual + 1;

    const costos = calcularCostosEntrenamiento(nivelSiguiente, config);

    if (
      propiedadActual.armas < costos.armas ||
      propiedadActual.municion < costos.municion ||
      propiedadActual.dolares < costos.dolares
    ) {
      return { error: 'No tienes suficientes recursos en esta propiedad para el entrenamiento.' };
    }

    const nivelEscuela = propiedadActual.habitaciones.find(h => h.configuracionHabitacionId === 'escuela_especializacion')?.nivel || 0;
    const duracion = calcularTiempoEntrenamiento(nivelSiguiente, config, nivelEscuela);

    const fechaInicio = new Date();
    const fechaFinalizacion = new Date(fechaInicio.getTime() + duracion * 1000);

    try {
      await prisma.$transaction(async (tx) => {
        await tx.propiedad.update({
          where: { id: propertyId },
          data: {
            armas: { decrement: costos.armas },
            municion: { decrement: costos.municion },
            dolares: { decrement: costos.dolares },
          },
        });

        await tx.colaEntrenamiento.create({
            data: {
                userId: user.id,
                propiedadId: propertyId,
                entrenamientoId: trainingId,
                nivelDestino: nivelSiguiente,
                fechaInicio,
                fechaFinalizacion,
            }
        });
      });

      revalidatePath('/training');
      revalidatePath('/overview'); 

      return { success: `¡El entrenamiento de ${config.nombre} a nivel ${nivelSiguiente} ha comenzado!` };
    } catch (error) {
      console.error('Error durante la transacción de entrenamiento:', error);
      return { error: 'Ocurrió un error en el servidor al intentar entrenar.' };
    }
}

