'use server';

import { cookies, headers } from 'next/headers';
import { getUserWithProgressByUsername } from '@/lib/data';
import prisma from './prisma/prisma';

const SESSION_COOKIE_NAME = 'vendetta-session';

export async function login(userId: string, username: string) {
  cookies().set(SESSION_COOKIE_NAME, username, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    maxAge: 60 * 60 * 24 * 7, // One week
    path: '/',
  });

  // Log login history
  try {
    const headerList = headers();
    const ip = headerList.get('x-forwarded-for') ?? 'unknown';
    const userAgent = headerList.get('user-agent') ?? 'unknown';

    await prisma.loginHistory.create({
      data: {
        userId: userId,
        ipAddress: ip,
        userAgent: userAgent,
      }
    })
  } catch (e) {
    console.error("Failed to log login history:", e);
  }
}

export async function logout() {
  cookies().delete(SESSION_COOKIE_NAME);
}

export async function getSessionUser() {
  const username = cookies().get(SESSION_COOKIE_NAME)?.value;
  if (!username) {
    return null;
  }
  try {
    const user = await getUserWithProgressByUsername(username);
    return user;
  } catch (error) {
    console.error("Failed to fetch session user:", error);
    return null;
  }
}

