import type { ConfiguracionTropa } from "@prisma/client";

interface Coordenadas {
    ciudad: number;
    barrio: number;
    edificio: number;
}

/**
 * Calcula la distancia del juego entre dos puntos basado en una jerarquía.
 * @param origen Las coordenadas de origen.
 * @param destino Las coordenadas de destino.
 * @returns La distancia calculada como un valor numérico.
 */
export function calcularDistancia(origen: Coordenadas, destino: Coordenadas): number {
    if (origen.ciudad !== destino.ciudad) {
        return Math.abs(origen.ciudad - destino.ciudad) * 20000;
    }
    if (origen.barrio !== destino.barrio) {
        return Math.abs(origen.barrio - destino.barrio) * 5000;
    }
    if (origen.edificio !== destino.edificio) {
        return Math.abs(origen.edificio - destino.edificio) * 1000;
    }
    // Si las coordenadas son idénticas, la distancia es una base mínima.
    return 1000;
}

/**
 * Determina la velocidad de la flota encontrando la velocidad de la tropa más lenta.
 * @param tropasEnviadas Un array de las tropas en la misión.
 * @param configs Un mapa o array de todas las configuraciones de tropas.
 * @returns La velocidad de la tropa más lenta.
 */
export async function calcularVelocidadFlota(
    tropasEnviadas: { id: string; cantidad: number }[],
    configs: Map<string, ConfiguracionTropa>
): Promise<number> {
    let velocidadMasLenta = Infinity;

    for (const tropa of tropasEnviadas) {
        if (tropa.cantidad > 0) {
            const config = configs.get(tropa.id);
            if (config && config.velocidad < velocidadMasLenta) {
                velocidadMasLenta = config.velocidad;
            }
        }
    }
    return velocidadMasLenta === Infinity ? 1000 : velocidadMasLenta;
}


/**
 * Calcula la duración del viaje en segundos usando la nueva fórmula.
 * @param distancia La distancia calculada con calcularDistancia.
 * @param velocidadFlota La velocidad de la tropa más lenta en la misión.
 * @returns La duración del viaje en segundos.
 */
export function calcularDuracionViaje(distancia: number, velocidadFlota: number): number {
    if (velocidadFlota <= 0) {
        return 86400 * 30; // 30 días como fallback para evitar división por cero.
    }

    // Duración en Segundos = redondear( ( (Distancia * 3.3479) / Velocidad de la Flota ) ^ 0.2 * 3600 )
    const baseCalculo = (distancia * 3.3479) / velocidadFlota;
    const duracionEnSegundos = Math.round(Math.pow(baseCalculo, 0.2) * 3600);

    return Math.max(10, duracionEnSegundos); // Mínimo de 10 segundos.
}

import type { FullConfiguracionHabitacion, FullPropiedad } from '../data';

/**
 * Calcula los costos de recursos para construir o mejorar una habitación a un nivel específico.
 */
export function calcularCostosNivel(
  nivel: number,
  config: FullConfiguracionHabitacion
): { armas: number; municion: number; dolares: number } {
  if (nivel <= 1) {
    return { armas: config.costoArmas, municion: config.costoMunicion, dolares: config.costoDolares };
  }

  const factor = nivel * nivel;

  const costoArmas = Math.floor(config.costoArmas * factor);
  const costoMunicion = Math.floor(config.costoMunicion * factor);
  const costoDolares = Math.floor(config.costoDolares * factor);

  return { armas: costoArmas, municion: costoMunicion, dolares: costoDolares };
}

/**
 * Calcula el tiempo de construcción para una habitación a un nivel específico.
 */
export function calcularTiempoConstruccion(
  nivel: number,
  config: FullConfiguracionHabitacion,
  nivelOficinaJefe: number
): number {
  if (nivel <= 0) {
    return config.duracion;
  }

  if (config.id === 'oficina_del_jefe') {
    if (nivel === 1) {
        return config.duracion;
    }
    const tiempoBase = config.duracion;
    return Math.floor(((nivel * nivel) * tiempoBase) / (nivel - 1));
  }

  const divisorOficina = Math.max(1, nivelOficinaJefe);

  const tiempoFinal = ((nivel * nivel) / divisorOficina) * config.duracion;

  return Math.max(5, Math.floor(tiempoFinal));
}

function calcularProduccionArmeria(nivel: number): number {
  if (nivel <= 0) return 0;
  return Math.trunc(10 * Math.pow((nivel + 1) / 2, 2));
}

function calcularProduccionMunicion(nivel: number): number {
  if (nivel <= 0) return 0;
  return Math.trunc(10 * Math.pow((nivel + 1) / 2, 2) + 10);
}

function calcularProduccionCerveceria(nivel: number): number {
    if (nivel <= 0) return 0;
    const signo = Math.sign(nivel);
    const entero = Math.trunc(nivel / 2);
    const residuo = nivel % 2;
    const residuoMasUno = (nivel + 1) % 2;

    const calculoIntermedio = ((1 + entero) * entero + (entero + 1) * residuo) * 10 + (residuoMasUno * 2);
    return signo * calculoIntermedio * 5;
}

function calcularProduccionTaberna(nivel: number): number {
    if (nivel <= 0) return 0;
    return Math.trunc(2 * Math.pow((nivel + 1) / 2, 2));
}

function calcularProduccionContrabando(nivel: number): number {
    if (nivel <= 0) return 0;
    return Math.trunc(21 * Math.pow((nivel + 1) / 2, 2));
}

export function calcularProduccionRecurso(idHabitacion: string, nivel: number): number {
  switch (idHabitacion) {
    case 'armeria':
      return calcularProduccionArmeria(nivel);
    case 'almacen_de_municion':
      return calcularProduccionMunicion(nivel);
    case 'cerveceria':
      return calcularProduccionCerveceria(nivel);
    case 'taberna':
      return calcularProduccionTaberna(nivel);
    case 'contrabando':
      return calcularProduccionContrabando(nivel);
    default:
      return 0;
  }
}

/**
 * Calcula la producción total por segundo para todos los recursos de una propiedad.
 * @param propiedad - La propiedad para la cual calcular la producción.
 * @returns Un objeto con la producción por segundo de cada recurso.
 */
export function calcularProduccionTotalPorSegundo(propiedad: FullPropiedad): { armas: number, municion: number, alcohol: number, dolares: number } {
  let produccionArmasPorSegundo = 0;
  let produccionMunicionPorSegundo = 0;
  let produccionAlcoholPorSegundo = 0;
  let produccionDolaresPorSegundo = 0;

  propiedad.habitaciones.forEach(habitacion => {
      const config = habitacion.configuracion;
      if (!config.produccionRecurso || habitacion.nivel === 0) return;

      const produccionPorHora = calcularProduccionRecurso(config.id, habitacion.nivel);
      const produccionPorSegundo = produccionPorHora / 3600;

      switch (config.produccionRecurso) {
          case 'armas':
              produccionArmasPorSegundo += produccionPorSegundo;
              break;
          case 'municion':
              produccionMunicionPorSegundo += produccionPorSegundo;
              break;
          case 'alcohol':
              produccionAlcoholPorSegundo += produccionPorSegundo;
              break;
          case 'dolares':
          case 'dolares_por_alcohol':
              produccionDolaresPorSegundo += produccionPorSegundo;
              break;
      }
  });

  return {
    armas: produccionArmasPorSegundo,
    municion: produccionMunicionPorSegundo,
    alcohol: produccionAlcoholPorSegundo,
    dolares: produccionDolaresPorSegundo,
  };
}


/**
 * Calcula la capacidad de almacenamiento de recursos de una propiedad.
 * @param propiedad - La propiedad con sus habitaciones.
 * @returns Un objeto con la capacidad máxima de cada recurso.
 */
export function calculateStorageCapacity(propiedad: FullPropiedad): { armas: number, municion: number, alcohol: number, dolares: number } {
    const BASE_CAPACITY = 10000;
    const CAPACITY_PER_LEVEL = 150000;

    let capacidadArmas = BASE_CAPACITY;
    let capacidadMunicion = BASE_CAPACITY;
    let capacidadAlcohol = BASE_CAPACITY;
    let capacidadDolares = BASE_CAPACITY;

    const almacenArmas = propiedad.habitaciones.find(h => h.configuracionHabitacionId === 'almacen_de_armas');
    if (almacenArmas) {
        capacidadArmas += almacenArmas.nivel * CAPACITY_PER_LEVEL;
    }

    const depositoMunicion = propiedad.habitaciones.find(h => h.configuracionHabitacionId === 'deposito_de_municion');
    if (depositoMunicion) {
        capacidadMunicion += depositoMunicion.nivel * CAPACITY_PER_LEVEL;
    }

    const almacenAlcohol = propiedad.habitaciones.find(h => h.configuracionHabitacionId === 'almacen_de_alcohol');
    if (almacenAlcohol) {
        capacidadAlcohol += almacenAlcohol.nivel * CAPACITY_PER_LEVEL;
    }

    const cajaFuerte = propiedad.habitaciones.find(h => h.configuracionHabitacionId === 'caja_fuerte');
    if (cajaFuerte) {
        capacidadDolares += cajaFuerte.nivel * CAPACITY_PER_LEVEL;
    }

    return {
        armas: capacidadArmas,
        municion: capacidadMunicion,
        alcohol: capacidadAlcohol,
        dolares: capacidadDolares,
    };
}

import type { UserWithProgress } from "../data";
import prisma from "../prisma/prisma";

export function calcularPuntosHabitaciones(user: UserWithProgress): number {
  if (!user.propiedades || user.propiedades.length === 0) return 0;

  return user.propiedades.reduce((totalPropiedades, propiedad) => {
    const puntosPropiedad = propiedad.habitaciones.reduce((totalHabitaciones, habitacion) => {
      const puntos = habitacion.configuracion.puntos * habitacion.nivel;
      return totalHabitaciones + puntos;
    }, 0);
    return totalPropiedades + puntosPropiedad;
  }, 0);
}

export function calcularPuntosTropas(user: UserWithProgress): number {
  if (!user.propiedades) return 0;

  return user.propiedades.reduce((totalPropiedades, propiedad) => {
    if (!propiedad.TropaUsuario) return totalPropiedades;
    const puntosPropiedad = propiedad.TropaUsuario.reduce((totalTropas, tropa) => {
      const puntos = tropa.configuracion.puntos * tropa.cantidad;
      return totalTropas + puntos;
    }, 0);
    return totalPropiedades + puntosPropiedad;
  }, 0);
}

export function calcularPuntosEntrenamientos(user: UserWithProgress): number {
  if (!user.entrenamientos) return 0;

  return user.entrenamientos.reduce((total, entrenamiento) => {
    const puntos = entrenamiento.configuracion.puntos * entrenamiento.nivel;
    return total + puntos;
  }, 0);
}

export async function calcularPoderAtaque(totalEdificios: number, honor: number): Promise<number> {
    if (totalEdificios < 1) totalEdificios = 1; // Ensure at least 1 property
    if (honor > 10) honor = 10; // Cap at max honor level defined
    if (honor < 0) honor = 0;

    const poder = await prisma.poderAtaque.findUnique({
        where: { propiedades_honor: { propiedades: totalEdificios, honor: honor } }
    });

    if (poder) {
        return poder.modificador;
    }

    // If no exact match, interpolate
    if (totalEdificios > 100) {
        const poderBase = await prisma.poderAtaque.findUnique({
            where: { propiedades_honor: { propiedades: 100, honor: honor } }
        });
        return poderBase ? Math.round(100 * poderBase.modificador / totalEdificios) : 29; // Fallback
    }

    const base = Math.floor(totalEdificios / 5) * 5;
    const next = base + 5;

    if (base === 0) { // Handle case for properties between 1 and 4
      const poderBase = await prisma.poderAtaque.findUnique({ where: { propiedades_honor: { propiedades: 1, honor: honor } } });
      return poderBase?.modificador || 100;
    }

    const [poderBase, poderNext] = await Promise.all([
        prisma.poderAtaque.findUnique({ where: { propiedades_honor: { propiedades: base, honor: honor } } }),
        prisma.poderAtaque.findUnique({ where: { propiedades_honor: { propiedades: next, honor: honor } } })
    ]);

    if (poderBase && poderNext) {
        const rango = (poderBase.modificador - poderNext.modificador) / 5;
        return Math.round(poderBase.modificador - (rango * (totalEdificios - base)));
    }

    return 100; // Final fallback
}

import type { ConfiguracionEntrenamiento } from '@prisma/client';

export function calcularCostosEntrenamiento(
  nivel: number,
  config: ConfiguracionEntrenamiento
): { armas: number; municion: number; dolares: number } {
  if (nivel <= 1) {
    return { armas: config.costoArmas, municion: config.costoMunicion, dolares: config.costoDolares };
  }

  const factor = nivel * nivel;

  const costoArmas = Math.floor(config.costoArmas * factor);
  const costoMunicion = Math.floor(config.costoMunicion * factor);
  const costoDolares = Math.floor(config.costoDolares * factor);

  return { armas: costoArmas, municion: costoMunicion, dolares: costoDolares };
}

export function calcularTiempoEntrenamiento(
  nivel: number,
  config: ConfiguracionEntrenamiento,
  nivelEscuela: number
): number {
  if (nivel <= 0) {
    return config.duracion;
  }

  // La fórmula es (nivel_objetivo * duracion_base) / nivel_escuela
  // Aseguramos que nivelEscuela sea al menos 1 para evitar división por cero.
  const divisorNivelEscuela = Math.max(1, nivelEscuela);

  const tiempoFinal = (nivel * config.duracion) / divisorNivelEscuela;

  return Math.max(5, Math.floor(tiempoFinal)); // Asegura un tiempo mínimo de 5 segundos.
}

import type { ConfiguracionTropa } from '@prisma/client';
import type { UserWithProgress } from '../data';

/**
 * Calcula el tiempo total de reclutamiento para una cantidad de tropas.
 * La nueva fórmula es: (duracion / nivel_campo) * cantidad
 * @param config - La configuración de la tropa.
 * @param cantidad - El número de tropas a reclutar.
 * @param nivelCampoEntrenamiento - El nivel actual del Campo de Entrenamiento de la propiedad.
 * @returns El tiempo de reclutamiento total en segundos.
 */
export function calcularTiempoReclutamiento(
  config: ConfiguracionTropa,
  cantidad: number,
  nivelCampoEntrenamiento: number
): number {
  if (cantidad <= 0) {
    return 0;
  }

  // Aseguramos que el nivel del campo no sea menor que 1 para evitar división por cero.
  const divisorNivelCampo = Math.max(1, nivelCampoEntrenamiento);

  const tiempoPorUnidad = config.duracion / divisorNivelCampo;
  const tiempoTotal = tiempoPorUnidad * cantidad;

  return Math.max(1, Math.floor(tiempoTotal)); // Aseguramos un tiempo mínimo de reclutamiento.
}


export function calcularStatsTropaConBonus(
    tropaConfig: ConfiguracionTropa, 
    entrenamientos: UserWithProgress['entrenamientos']
  ): { ataqueActual: number, defensaActual: number } {

    const entrenamientosMap = new Map(entrenamientos.map(e => [e.configuracionEntrenamientoId, e.nivel]));

    let ataqueBase = tropaConfig.ataque;
    let defensaBase = tropaConfig.defensa;

    const bonusAtaqueIds = tropaConfig.bonusAtaque || [];
    const bonusDefensaIds = tropaConfig.bonusDefensa || [];

    // Sumar los niveles de todos los entrenamientos relevantes para el ataque
    const sumaNivelesAtaque = bonusAtaqueIds.reduce((sum, id) => {
        return sum + (entrenamientosMap.get(id) || 0);
    }, 0);

    // Sumar los niveles de todos los entrenamientos relevantes para la defensa
    const sumaNivelesDefensa = bonusDefensaIds.reduce((sum, id) => {
        return sum + (entrenamientosMap.get(id) || 0);
    }, 0);

    // Aplicar la fórmula: ENTERO(BASE*RAIZ(SUMA_NIVELES)/10+BASE)
    const ataqueActual = Math.floor(ataqueBase * (Math.sqrt(sumaNivelesAtaque) / 10) + ataqueBase);
    const defensaActual = Math.floor(defensaBase * (Math.sqrt(sumaNivelesDefensa) / 10) + defensaBase);

    return {
      ataqueActual,
      defensaActual,
    };
  }

